package stream

import (
	"bytes"
	"testing"
)

// TestTokenizePlaylist is the table floor for playlist token propagation
// (incident 2026-10-31: cookie-less TV clients 401 on bare segment URIs).
func TestTokenizePlaylist(t *testing.T) {
	const tok = "it1|1793444792|cf131cc2d40fbec1"
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"segment line", "seg-00000.m4s", "seg-00000.m4s?token=" + tok},
		{"tail segment line", "t/seg-00007.m4s", "t/seg-00007.m4s?token=" + tok},
		{"variant playlist line", "rend0/index.m3u8", "rend0/index.m3u8?token=" + tok},
		{"map init attr", `#EXT-X-MAP:URI="init.mp4"`, `#EXT-X-MAP:URI="init.mp4?token=` + tok + `"`},
		{"media rendition attr", `#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID="vo",NAME="Orig",DEFAULT=YES,URI="rend0/index.m3u8"`,
			`#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID="vo",NAME="Orig",DEFAULT=YES,URI="rend0/index.m3u8?token=` + tok + `"`},
		{"plain tag untouched", "#EXTINF:4.004000,", "#EXTINF:4.004000,"},
		{"header untouched", "#EXTM3U", "#EXTM3U"},
		{"endlist untouched", "#EXT-X-ENDLIST", "#EXT-X-ENDLIST"},
		{"absolute uri untouched", `#EXT-X-MAP:URI="https://cdn.example/init.mp4"`, `#EXT-X-MAP:URI="https://cdn.example/init.mp4"`},
		{"existing query extends", "seg-00001.m4s?mseq=7", "seg-00001.m4s?mseq=7&token=" + tok},
		{"already tokened is idempotent", "seg-00001.m4s?token=other", "seg-00001.m4s?token=other"},
		{"empty attr value untouched", `#EXT-X-MAP:URI=""`, `#EXT-X-MAP:URI=""`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			in := []byte("#EXTM3U\n" + tc.in + "\n#EXT-X-ENDLIST\n")
			want := "#EXTM3U\n" + tc.want + "\n#EXT-X-ENDLIST\n"
			if got := string(tokenizePlaylist(in, tok)); got != want {
				t.Fatalf("tokenizePlaylist =\n%s\nwant\n%s", got, want)
			}
			// Idempotence: rewriting the rewrite changes nothing.
			if got := string(tokenizePlaylist(tokenizePlaylist(in, tok), tok)); got != want {
				t.Fatalf("second pass =\n%s\nwant (idempotent)\n%s", got, want)
			}
		})
	}
	t.Run("crlf_line_endings_preserved", func(t *testing.T) {
		in := []byte("#EXTM3U\r\n#EXT-X-MAP:URI=\"init.mp4\"\r\nseg-00000.m4s\r\n")
		want := "#EXTM3U\r\n#EXT-X-MAP:URI=\"init.mp4?token=" + tok + "\"\r\nseg-00000.m4s?token=" + tok + "\r\n"
		if got := string(tokenizePlaylist(in, tok)); got != want {
			t.Fatalf("tokenizePlaylist =\n%q\nwant\n%q", got, want)
		}
	})
	t.Run("empty_token_passthrough", func(t *testing.T) {
		in := []byte("#EXTM3U\nseg-00000.m4s\n")
		if got := tokenizePlaylist(in, ""); !bytes.Equal(got, in) {
			t.Fatalf("empty token rewrote the body: %q", got)
		}
	})
	t.Run("blank_lines_preserved", func(t *testing.T) {
		in := []byte("#EXTM3U\n\nseg-00000.m4s\n\n")
		want := "#EXTM3U\n\nseg-00000.m4s?token=" + tok + "\n\n"
		if got := string(tokenizePlaylist(in, tok)); got != want {
			t.Fatalf("tokenizePlaylist = %q, want %q", got, want)
		}
	})
}
